function apply(){const p=state.prefs;const mascotOptions=document.querySelector("[data-companion-options]");if(mascotOptions)mascotOptions.hidden=!p.danceCompanion;updateTimeline();for(const k of ['quality','targetFPS','hdrMode','mode','intensity','dynamicVisuals','coverPalette','particleColor','responsiveness','fluidity','iridescence','depth','spectralDetail','kaleidoscope','kaleidoscopeMode','autoDirection','rollercoaster','cameraSpeed','cameraZoom'])reactor[k]=p[k];reactor.appearance={...reactor.appearance,...p};reactor.visualTheme=p.visualTheme;reactor.setVisualSync(p);document.body.classList.toggle('music-only',p.musicOnly);reactor.setMusicOnly(p.musicOnly);$('#music-only').setAttribute('aria-pressed',String(p.musicOnly));paintListeningMode(constellation.isOpen?'constellation':p.musicOnly?'music':'visualizer');sona.apply({...p,musicOnly:p.musicOnly||!state.active});feedback.apply({...p,musicOnly:p.musicOnly||!state.active});void rpc('visuals',{enabled:state.active&&!p.musicOnly&&!reactor.sceneSuspended}).catch(()=>{});}
