async function loadSongProfile(id){if(!id)return;listeningProfile=null;listeningEdit=null;try{const value=await rpc(needsSongAnalysis(state.prefs)?'analyzeSong':'songProfile',{id});if(current()?.id!==id)return;reactor.updateSongProfile(id,value.profile);listeningProfile=value.profile;listeningEdit=value.edit;updateTimeline();if(!value.profile&&!value.error&&value.job?.running)setTimeout(async()=>{if(current()?.id!==id)return;const result=await rpc('songProfile',{id}).catch(()=>null);if(current()?.id!==id)return;if(result?.profile){reactor.updateSongProfile(id,result.profile);listeningProfile=result.profile;listeningEdit=result.edit;updateTimeline();}else if(!result?.error)void loadSongProfile(id);},3000);}catch{}}
