function renderPlayback(){const s=audio.snapshot;showLevelPreparation(s.levelPreparing?{error:s.levelError,title:current()?.title,progress:s.levelProgress?.id===s.id?s.levelProgress.progress:null}:null);reactor.desktopSource=s.capturing?{}:null;feedback.desktopListening=!!s.capturing;for(const id of ['seek','volume','next','previous','shuffle','repeat','volume-value'])$('#'+id).disabled=!!s.capturing;paintIcon($('#play'),audio.paused&&!s.levelPreparing?'play':'pause');$('#play').setAttribute('aria-label',audio.paused&&!s.levelPreparing?'Play':'Pause');$('#shuffle').setAttribute('aria-pressed',String(!!s.shuffle));$('#repeat').setAttribute('aria-pressed',String(s.repeat===1));$('#seek').setAttribute('aria-valuetext',time(audio.currentTime)+' of '+time(audio.duration));$('#volume').setAttribute('aria-valuetext',Math.round(audio.volume*100)+' percent');$('#elapsed').textContent=time(audio.currentTime);$('#duration').textContent=time(audio.duration);if(document.activeElement!==$('#seek'))$('#seek').value=audio.duration?audio.currentTime/audio.duration*1000:0;if(document.activeElement!==$('#volume'))$('#volume').value=audio.volume*100;$('#volume-value').textContent=Number((audio.volume*100).toFixed(1))+'%';$('#playback-problem').hidden=!s.error;$('#playback-problem-message').textContent=s.error||'';$('#playback-status').textContent=s.captureError|| (s.capturing?'Listening to other apps':s.buffering?'Loading audio…':'');}
audio.addEventListener('trackchange',()=>{reactor.resetAnalysis();renderNow();if(state.view==='queue')void queue();const t=current();if(t&&discoveryId!==t.id){discoveryId=t.id;void rpc('research',{id:t.id}).then(updated=>{Object.assign(t,updated);if(current()?.id===t.id){artKey='';renderNow();}}).catch(()=>{});}});audio.addEventListener('timeupdate',renderPlayback);
async function poll(generation=++pollGeneration){if(!state.active||generation!==pollGeneration)return;try{const s=await rpc('state',{queueRevision:audio.snapshot.queueRevision??-1});if(generation!==pollGeneration)return;if(s.capturing!==audio.snapshot.capturing)reactor.resetAnalysis();audio.update(s);}catch{}if(state.active&&generation===pollGeneration)analysisTimer=setTimeout(()=>poll(generation),400);}
window.mobileActive=active=>{state.active=active;feedback.apply({...state.prefs,musicOnly:state.prefs.musicOnly||!active});pollGeneration++;clearTimeout(analysisTimer);sona.apply({...state.prefs,musicOnly:state.prefs.musicOnly||!active});void reactor.foreground(active);if(active)void poll();};document.addEventListener('visibilitychange',()=>window.mobileActive(!document.hidden));
function tracks(){let ts=state.tracks.filter(t=>t.available!==false);if(state.filter==='favorites')ts=ts.filter(t=>t.favorite);else if(state.filter==='downloaded')ts=ts.filter(t=>t.downloaded);else if(state.filter==='mixes')ts=ts.filter(t=>t.kind==='mix');else if(state.filter.startsWith('source:'))ts=ts.filter(t=>t.sourceId===state.filter.slice(7)||Object.hasOwn(t.sourceOrders||{},state.filter.slice(7)));else if(state.filter.startsWith('playlist:')){const p=state.playlists.find(p=>p.id===state.filter.slice(9));ts=ts.filter(t=>p?.tracks.includes(t.id));}else if(state.filter.startsWith('genre:'))ts=ts.filter(t=>(t.genre||'').split(/[,;]/).some(g=>g.trim()===state.filter.slice(6)));
 const sourceOrder=t=>state.filter.startsWith('source:')?(t.sourceOrders?.[state.filter.slice(7)]??t.playlistIndex??999999):(t.playlistIndex??999999);const selectedPlaylist=state.playlists.find(p=>'playlist:'+p.id===state.filter);if(selectedPlaylist&&state.sort==='playlist')ts.forEach(t=>t.mobileOrder=selectedPlaylist.tracks.indexOf(t.id));const query=state.search.toLocaleLowerCase();ts=ts.filter(t=>[t.title,t.artist,t.album,t.genre].join(' ').toLocaleLowerCase().includes(query));return ts.sort((a,b)=>state.sort==='title'?a.title.localeCompare(b.title):state.sort==='artist'?(a.artist||'').localeCompare(b.artist||''):state.sort==='recent'?(b.lastPlayed||0)-(a.lastPlayed||0):state.sort==='plays'?(b.plays||0)-(a.plays||0):state.sort==='added'?(b.addedAt||0)-(a.addedAt||0):selectedPlaylist?(a.mobileOrder-b.mobileOrder):sourceOrder(a)-sourceOrder(b));
}
function trackRows(ts){return ts.map(t=>`<div class="track ${t.id===audio.snapshot.id?'current':''}"><button class="track-play" data-play="${esc(t.id)}" aria-label="Play ${esc(t.title)}"><span class="art">${cover(t)}<span class="art-play" aria-hidden="true">▶</span></span><span class="name"><strong>${esc(t.title)}</strong><small>${esc(t.artist||'Artist unknown')}</small></span><time>${time(t.duration)}</time></button><button class="round" data-details="${esc(t.id)}" aria-label="Details for ${esc(t.title)}">⋯</button></div>`).join('');}
