let modeRequest=0;
async function setListeningMode(mode){const request=++modeRequest;
 if(mode==='constellation'){close();if(document.body.classList.contains('immersed'))actions.immerse();const opening=constellation.open();preferences({musicOnly:false});if(audio.snapshot.capturing)await rpc('captureStop');if(request===modeRequest)await opening;return;}
 if(mode==='music'&&constellation.isOpen){state.prefs.musicOnly=true;reactor.setMusicOnly(true);}
 if(mode!=='constellation'&&constellation.isOpen)constellation.close();
 if(mode!=='visualizer'){if(document.body.classList.contains('immersed'))actions.immerse();if(audio.snapshot.capturing)await rpc('captureStop');}
 if(request!==modeRequest)return;close();preferences({musicOnly:mode==='music'});
}
